CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS transactions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),content_id UUID,buyer_id UUID NOT NULL,seller_id UUID NOT NULL,amount_cents BIGINT NOT NULL,currency TEXT NOT NULL DEFAULT 'IDR',transaction_status TEXT NOT NULL DEFAULT 'pending',offer_message TEXT,response_message TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_payment_transactions_buyer ON transactions(buyer_id);
CREATE INDEX IF NOT EXISTS idx_payment_transactions_seller ON transactions(seller_id);
CREATE INDEX IF NOT EXISTS idx_payment_transactions_status ON transactions(transaction_status);
CREATE TABLE IF NOT EXISTS wallet_accounts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL,environment TEXT NOT NULL DEFAULT 'development',currency TEXT NOT NULL DEFAULT 'IDR',available_balance_cents BIGINT NOT NULL DEFAULT 0,held_balance_cents BIGINT NOT NULL DEFAULT 0,total_topup_cents BIGINT NOT NULL DEFAULT 0,total_spend_cents BIGINT NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'active',metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(user_id,environment,currency));
CREATE TABLE IF NOT EXISTS wallet_topups(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL,account_id UUID NOT NULL,environment TEXT NOT NULL DEFAULT 'development',amount_cents BIGINT NOT NULL,fee_cents BIGINT NOT NULL DEFAULT 0,net_amount_cents BIGINT NOT NULL,currency TEXT NOT NULL DEFAULT 'IDR',payment_provider TEXT NOT NULL DEFAULT 'mock',payment_method TEXT,external_reference TEXT,checkout_url TEXT,payment_payload JSONB NOT NULL DEFAULT '{}'::jsonb,description TEXT,status TEXT NOT NULL DEFAULT 'pending',paid_at TIMESTAMPTZ,expired_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(external_reference));
CREATE TABLE IF NOT EXISTS wallet_ledger_entries(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL,account_id UUID NOT NULL,environment TEXT NOT NULL DEFAULT 'development',currency TEXT NOT NULL DEFAULT 'IDR',direction TEXT NOT NULL,amount_cents BIGINT NOT NULL,balance_after_cents BIGINT NOT NULL,entry_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'posted',reference_type TEXT,reference_id UUID,description TEXT,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS wallet_withdrawals(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL,account_id UUID NOT NULL,environment TEXT NOT NULL DEFAULT 'development',amount_cents BIGINT NOT NULL,fee_cents BIGINT NOT NULL DEFAULT 0,net_amount_cents BIGINT NOT NULL,currency TEXT NOT NULL DEFAULT 'IDR',bank_code TEXT NOT NULL,bank_name TEXT NOT NULL,bank_account_name TEXT NOT NULL,bank_account_number_masked TEXT NOT NULL,bank_account_number_hash TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending_review',note TEXT,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,requested_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),processed_at TIMESTAMPTZ,cancelled_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_wallet_ledger_user_created ON wallet_ledger_entries(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_wallet_topups_user_created ON wallet_topups(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_wallet_withdrawals_user_created ON wallet_withdrawals(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS payment_attempts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),transaction_id UUID,provider TEXT NOT NULL,provider_reference TEXT,request_idempotency_key TEXT NOT NULL,amount_cents BIGINT NOT NULL,currency TEXT NOT NULL DEFAULT 'IDR',status TEXT NOT NULL DEFAULT 'pending',raw_response JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(request_idempotency_key));
CREATE TABLE IF NOT EXISTS refunds(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),payment_attempt_id UUID NOT NULL,amount_cents BIGINT NOT NULL,reason TEXT,status TEXT NOT NULL DEFAULT 'pending',provider_reference TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());